{
  "name": "KTP Data Extractor Pro",
  "description": "Extract data from Indonesian KTP (ID Card) using Gemini AI. Capture from camera or upload, review extracted fields, and save to Google Sheets.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface KtpData {
  nik: string;
  nama: string;
  tempatTglLahir: string;
  jenisKelamin: string;
  alamat: string;
  rtRw: string;
  kelDesa: string;
  kecamatan: string;
  agama: string;
  statusPerkawinan: string;
  pekerjaan: string;
  kewarganegaraan: string;
  berlakuHingga: string;
}

export type ExtractionStatus = 'idle' | 'processing' | 'success' | 'error';

export interface AppState {
  image: string | null;
  extractedData: KtpData | null;
  status: ExtractionStatus;
  errorMessage: string | null;
}

import { GoogleGenAI, Type } from "@google/genai";
import { KtpData } from "../types";

export const extractKtpData = async (base64Image: string): Promise<KtpData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Remove the prefix (e.g., "data:image/png;base64,")
  const imageData = base64Image.split(',')[1] || base64Image;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageData,
          },
        },
        {
          text: `Extract all fields from this Indonesian KTP (ID Card) image. 
          Respond strictly in JSON format matching the schema provided. 
          If a field is not readable, return an empty string. 
          Ensure NIK is 16 digits. Normalize formatting for Alamat, RT/RW, etc.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          nik: { type: Type.STRING, description: 'NIK number' },
          nama: { type: Type.STRING, description: 'Full name' },
          tempatTglLahir: { type: Type.STRING, description: 'Place and Date of Birth' },
          jenisKelamin: { type: Type.STRING, description: 'LAKI-LAKI or PEREMPUAN' },
          alamat: { type: Type.STRING, description: 'Street address' },
          rtRw: { type: Type.STRING, description: 'RT/RW' },
          kelDesa: { type: Type.STRING, description: 'Village/Administrative area' },
          kecamatan: { type: Type.STRING, description: 'District' },
          agama: { type: Type.STRING, description: 'Religion' },
          statusPerkawinan: { type: Type.STRING, description: 'Marital status' },
          pekerjaan: { type: Type.STRING, description: 'Occupation' },
          kewarganegaraan: { type: Type.STRING, description: 'Nationality' },
          berlakuHingga: { type: Type.STRING, description: 'Expiry date or SEUMUR HIDUP' },
        },
        required: ["nik", "nama"],
      },
    },
  });

  try {
    const jsonStr = response.text.trim();
    return JSON.parse(jsonStr) as KtpData;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("Could not parse KTP data. Please ensure the image is clear.");
  }
};

import React, { useRef, useState, useCallback } from 'react';

interface CameraViewProps {
  onCapture: (base64: string) => void;
}

export const CameraView: React.FC<CameraViewProps> = ({ onCapture }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isStarted, setIsStarted] = useState(false);

  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      setIsStarted(true);
    } catch (err) {
      console.error("Error accessing camera:", err);
      alert("Please allow camera access.");
    }
  };

  const stopCamera = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
      setIsStarted(false);
    }
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        onCapture(dataUrl);
        stopCamera();
      }
    }
  };

  return (
    <div className="flex flex-col items-center gap-4 w-full">
      {!isStarted ? (
        <button
          onClick={startCamera}
          className="flex items-center gap-2 px-6 py-3 bg-red-600 text-white rounded-full hover:bg-red-700 transition shadow-lg font-semibold"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          Buka Kamera
        </button>
      ) : (
        <div className="relative w-full max-w-md bg-black rounded-xl overflow-hidden shadow-2xl">
          <video
            ref={videoRef}
            autoPlay
            playsInline
            className="w-full h-auto aspect-[4/3] object-cover"
          />
          {/* Guide Overlay */}
          <div className="absolute inset-0 border-2 border-dashed border-white/50 m-8 rounded-lg pointer-events-none flex items-center justify-center">
             <div className="text-white text-xs bg-black/50 px-2 py-1 rounded">Posisikan KTP di dalam kotak</div>
          </div>

          <div className="absolute bottom-4 inset-x-0 flex justify-center gap-4">
            <button
              onClick={capture}
              className="p-4 bg-white rounded-full shadow-lg hover:bg-gray-100 transition"
            >
              <div className="w-8 h-8 rounded-full border-4 border-red-600" />
            </button>
            <button
              onClick={stopCamera}
              className="p-4 bg-red-600 text-white rounded-full shadow-lg hover:bg-red-700 transition"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>
      )}
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

import React from 'react';
import { KtpData } from '../types';

