import React, { useState, useCallback } from 'react';
import { CameraView } from './components/CameraView';
import { KtpForm } from './components/KtpForm';
import { extractKtpData } from './services/geminiService';
import { AppState, KtpData } from './types';

// IMPORTANT: Replace this with your Google Apps Script Web App URL after deployment
const GAS_URL = 'https://script.google.com/macros/s/REPLACE_WITH_YOUR_ID/exec';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    image: null,
    extractedData: null,
    status: 'idle',
    errorMessage: null,
  });

  const [saving, setSaving] = useState(false);

  const handleCapture = async (base64: string) => {
    setState(prev => ({ ...prev, image: base64, status: 'processing', errorMessage: null }));

    try {
      const data = await extractKtpData(base64);
      setState(prev => ({ ...prev, extractedData: data, status: 'success' }));
    } catch (err: any) {
      setState(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMessage: err.message || "Gagal mengekstrak data. Pastikan gambar jelas." 
      }));
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        handleCapture(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveToSpreadsheet = async () => {
    if (!state.extractedData || !state.image) return;

    setSaving(true);
    try {
      // Logic for saving to Google Sheets via GAS
      // We pass the data + image as base64
      const response = await fetch(GAS_URL, {
        method: 'POST',
        mode: 'no-cors', // standard for GAS web apps unless CORS is perfectly configured
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...state.extractedData,
          image: state.image
        })
      });

      alert("Data berhasil dikirim ke antrean Spreadsheet!");
      setState({
        image: null,
        extractedData: null,
        status: 'idle',
        errorMessage: null,
      });
    } catch (err) {
      console.error("Error saving data:", err);
      alert("Gagal menyimpan ke Spreadsheet. Periksa konfigurasi Apps Script Anda.");
    } finally {
      setSaving(false);
    }
  };

  const reset = () => {
    setState({
      image: null,
      extractedData: null,
      status: 'idle',
      errorMessage: null,
    });
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 md:py-12">
      <header className="text-center mb-10">
        <h1 className="text-3xl md:text-4xl font-extrabold text-gray-900 mb-2">
          KTP <span className="text-red-600">Scan & Sync</span>
        </h1>
        <p className="text-gray-600">Otomatisasi input data KTP dengan kecerdasan AI</p>
      </header>

      <main className="flex flex-col items-center gap-8">
        {state.status === 'idle' && (
          <div className="w-full flex flex-col items-center gap-6">
            <CameraView onCapture={handleCapture} />

            <div className="flex items-center gap-4 w-full max-w-md">
              <div className="h-px bg-gray-300 flex-1"></div>
              <span className="text-gray-400 text-sm font-medium">ATAU</span>
              <div className="h-px bg-gray-300 flex-1"></div>
            </div>

            <label className="cursor-pointer group flex items-center gap-2 px-6 py-2 border-2 border-gray-200 rounded-lg hover:border-red-500 transition">
              <svg className="w-5 h-5 text-gray-400 group-hover:text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              <span className="text-gray-600 group-hover:text-red-600 font-medium">Unggah Foto KTP</span>
              <input type="file" className="hidden" accept="image/*" onChange={handleFileUpload} />
            </label>
          </div>
        )}

        {state.status === 'processing' && (
          <div className="flex flex-col items-center justify-center p-12 bg-white rounded-2xl shadow-xl w-full max-w-md animate-pulse">
            <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-4" />
            <p className="text-lg font-bold text-gray-800">Mengekstrak Data...</p>
            <p className="text-sm text-gray-500 text-center mt-2">Gemini AI sedang memproses foto KTP Anda</p>
          </div>
        )}

        {state.status === 'error' && (
          <div className="w-full max-w-md p-6 bg-red-50 border border-red-200 rounded-xl flex flex-col items-center text-center">
            <svg className="w-12 h-12 text-red-500 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
            <h3 className="text-lg font-bold text-red-800 mb-2">Terjadi Kesalahan</h3>
            <p className="text-red-600 mb-6">{state.errorMessage}</p>
            <button onClick={reset} className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition">
              Coba Lagi
            </button>
          </div>
        )}

        {state.status === 'success' && state.extractedData && state.image && (
          <div className="w-full grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
            <div className="flex flex-col gap-4">
              <div className="bg-white p-2 rounded-xl shadow-lg border border-gray-100 overflow-hidden">
                <img 
                  src={state.image} 
                  alt="Captured KTP" 
                  className="w-full h-auto rounded-lg object-contain"
                />
              </div>
              <p className="text-xs text-gray-500 italic text-center">Pratinjau gambar asli KTP yang dipindai</p>
            </div>

            <KtpForm 
              data={state.extractedData}
              onChange={(newData) => setState(prev => ({ ...prev, extractedData: newData }))}
              onSubmit={handleSaveToSpreadsheet}
              onReset={reset}
              isLoading={saving}
            />
          </div>
        )}
      </main>

      <footer className="mt-16 text-center text-gray-400 text-xs">
        <p>&copy; 2024 KTP Data Extractor. Powered by Gemini Flash 1.5.</p>
        <p className="mt-2">Pastikan pencahayaan cukup saat mengambil foto.</p>
      </footer>
    </div>
  );
};

export default App;

/**
 * PANDUAN IMPLEMENTASI (BACA DULU):
 * 1. Buka https://script.google.com/
 * 2. Buat proyek baru.
 * 3. Copy-paste kode di bawah ini ke editor script.
 * 4. Buat Google Sheet baru, ambil ID-nya (dari URL).
 * 5. Update ID_SHEET dan NAMA_SHEET di bawah.
 * 6. Klik "Deploy" -> "New Deployment" -> Select "Web App".
 * 7. Set "Execute as": Me, "Who has access": "Anyone".
 * 8. Copy URL Web App-nya ke file App.tsx di bagian `GAS_URL`.
 */

const ID_SHEET = 'MASUKKAN_ID_SPREADSHEET_ANDA';
const NAMA_SHEET = 'Sheet1';
const ID_FOLDER_FOTO = 'MASUKKAN_ID_FOLDER_DRIVE_JIKA_INGIN_SIMPAN_FOTO';

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(ID_SHEET);
    const sheet = ss.getSheetByName(NAMA_SHEET);

    // Header setup if empty
    if (sheet.getLastRow() === 0) {
      sheet.appendRow([
        'Waktu', 'NIK', 'Nama', 'Tempat/Tgl Lahir', 'Jenis Kelamin', 
        'Alamat', 'RT/RW', 'Kel/Desa', 'Kecamatan', 'Agama', 
        'Status', 'Pekerjaan', 'Kewarganegaraan', 'Berlaku', 'URL Foto'
      ]);
    }

    let fotoUrl = "Tidak ada foto";

    // Save image to Drive if provided
    if (data.image && ID_FOLDER_FOTO !== 'MASUKKAN_ID_FOLDER_DRIVE_JIKA_INGIN_SIMPAN_FOTO') {
      const folder = DriveApp.getFolderById(ID_FOLDER_FOTO);
      const fileName = "KTP_" + data.nik + "_" + new Date().getTime() + ".jpg";
      const contentType = "image/jpeg";
      const base64Data = data.image.split(',')[1];
      const blob = Utilities.newBlob(Utilities.base64Decode(base64Data), contentType, fileName);
      const file = folder.createFile(blob);
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      fotoUrl = file.getUrl();
    }

    // Append data
    sheet.appendRow([
      new Date(),
      data.nik,
      data.nama,
      data.tempatTglLahir,
      data.jenisKelamin,
      data.alamat,
      data.rtRw,
      data.kelDesa,
      data.kecamatan,
      data.agama,
      data.statusPerkawinan,
      data.pekerjaan,
      data.kewarganegaraan,
      data.berlakuHingga,
      fotoUrl
    ]);

    return ContentService.createTextOutput(JSON.stringify({ status: 'success' }))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

import React, { useRef, useState, useCallback } from 'react';

interface CameraViewProps {
  onCapture: (base64: string) => void;
}

export const CameraView: React.FC<CameraViewProps> = ({ onCapture }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isStarted, setIsStarted] = useState(false);

  const startCamera = async () => {
    try {
      // Optimized for mobile: prioritize high resolution and environment (back) camera
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { 
          facingMode: 'environment', 
          width: { ideal: 1920 }, 
          height: { ideal: 1080 } 
        }
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      setIsStarted(true);
    } catch (err) {
      console.error("Error accessing camera:", err);
      alert("Gagal mengakses kamera. Pastikan Anda memberikan izin kamera di browser HP Anda.");
    }
  };

  const stopCamera = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
      setIsStarted(false);
    }
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // Use actual video dimensions for capture
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Simple vibration feedback for mobile if supported
        if ('vibrate' in navigator) navigator.vibrate(50);

        ctx.drawImage(video, 0, 0);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        onCapture(dataUrl);
        stopCamera();
      }
    }
  };

  return (
    <div className="flex flex-col items-center gap-4 w-full">
      {!isStarted ? (
        <button
          onClick={startCamera}
          className="w-full max-w-xs flex items-center justify-center gap-3 px-8 py-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 active:scale-95 transition shadow-xl font-bold text-lg"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          Ambil Foto KTP
        </button>
      ) : (
        <div className="relative w-full max-w-md bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-gray-800">
          <video
            ref={videoRef}
            autoPlay
            playsInline
            className="w-full h-auto aspect-[3/4] object-cover md:aspect-video"
          />

          {/* Mobile Overlay Guide */}
