/**
 * PANDUAN DEPLOY KE GOOGLE APPS SCRIPT:
 * 1. Buka https://script.google.com/
 * 2. Buat proyek baru "KTP Backend".
 * 3. Copy-paste kode ini ke editor Code.gs.
 * 4. Ganti ID_SHEET dengan ID Google Sheet Anda (dari URL Sheet).
 * 5. Ganti ID_FOLDER_FOTO dengan ID Folder Google Drive untuk menyimpan foto.
 * 6. Klik "Deploy" (Pojok kanan atas) -> "New Deployment".
 * 7. Pilih tipe "Web App".
 * 8. Execute as: "Me" (Email Anda).
 * 9. Who has access: "Anyone".
 * 10. Klik Deploy -> Authorize -> Copy "Web App URL" (Inilah URL Backend).
 * 11. Masukkan URL tersebut ke variabel GAS_URL di file App.tsx.
 */

const ID_SHEET = 'MASUKKAN_ID_SPREADSHEET_DI_SINI';
const NAMA_SHEET = 'Sheet1';
const ID_FOLDER_FOTO = 'MASUKKAN_ID_FOLDER_DRIVE_DI_SINI';

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(ID_SHEET);
    const sheet = ss.getSheetByName(NAMA_SHEET) || ss.getSheets()[0];

    // Setup Header jika sheet masih kosong
    if (sheet.getLastRow() === 0) {
      sheet.appendRow([
        'Waktu Input', 'NIK', 'Nama Lengkap', 'Tempat/Tgl Lahir', 'Jenis Kelamin', 
        'Alamat', 'RT/RW', 'Kel/Desa', 'Kecamatan', 'Agama', 
        'Status Perkawinan', 'Pekerjaan', 'Kewarganegaraan', 'Berlaku Hingga', 'Link Foto KTP'
      ]);
      // Beri style tebal pada header
      sheet.getRange(1, 1, 1, 15).setFontWeight('bold').setBackground('#f3f3f3');
    }

    let fotoUrl = "Folder Drive belum diset";

    // Simpan foto ke Google Drive jika Folder ID valid
    if (data.image && ID_FOLDER_FOTO.length > 20) {
      try {
        const folder = DriveApp.getFolderById(ID_FOLDER_FOTO);
        const fileName = "KTP_" + (data.nik || "TanpaNIK") + "_" + Utilities.formatDate(new Date(), "GMT+7", "yyyyMMdd_HHmm") + ".jpg";
        const base64Data = data.image.split(',')[1];
        const blob = Utilities.newBlob(Utilities.base64Decode(base64Data), "image/jpeg", fileName);
        const file = folder.createFile(blob);
        file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        fotoUrl = file.getUrl();
      } catch (fError) {
        fotoUrl = "Error Simpan Foto: " + fError.toString();
      }
    }

    // Masukkan data ke baris baru
    sheet.appendRow([
      new Date(),
      "'" + data.nik, // Gunakan kutip satu agar NIK tidak dianggap angka scientific
      data.nama,
      data.tempatTglLahir,
      data.jenisKelamin,
      data.alamat,
      data.rtRw,
      data.kelDesa,
      data.kecamatan,
      data.agama,
      data.statusPerkawinan,
      data.pekerjaan,
      data.kewarganegaraan,
      data.berlakuHingga,
      fotoUrl
    ]);

    return ContentService.createTextOutput(JSON.stringify({ status: 'success' }))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

