import { AppState } from './types';

/**
 * PENTING: Ganti URL di bawah ini dengan URL Web App dari Google Apps Script Anda.
 */
const GAS_URL = 'https://script.google.com/macros/s/AKfycbxPJd_-ZRAo6xlxsBWju7EIcqo7r8HX1zVNp3NW7YsY80DnUDO2-B5yruxlzA9siQrk/exec';

