  const [state, setState] = useState<AppState>({
    image: null,
    extractedData: null,
    status: 'idle',
    errorMessage: null,
  });

  const [saving, setSaving] = useState(false);
  const [currentUrl, setCurrentUrl] = useState('');
  const [isEditorUrl, setIsEditorUrl] = useState(false);

  useEffect(() => {
    const url = window.location.href;
    setCurrentUrl(url);
    // Deteksi jika link adalah link editor ai.studio
    if (url.includes('ai.studio') || url.includes('apps/drive')) {
      setIsEditorUrl(true);
    } else {
      setIsEditorUrl(false);
    }
  }, []);

  const handleCapture = async (base64: string) => {
    setState(prev => ({ ...prev, image: base64, status: 'processing', errorMessage: null }));

    try {
      const data = await extractKtpData(base64);
      setState(prev => ({ ...prev, extractedData: data, status: 'success' }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      setState(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMessage: err.message || "Gagal mengekstrak data. Pastikan gambar jelas." 
      }));
    }
