  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        handleCapture(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveToSpreadsheet = async () => {
    if (!state.extractedData || !state.image) return;

    setSaving(true);
    try {
      await fetch(GAS_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...state.extractedData,
          image: state.image
        })
      });

      alert("✅ BERHASIL! Data & Foto KTP telah terkirim ke Google Sheets.");
      setState({
        image: null,
        extractedData: null,
        status: 'idle',
        errorMessage: null,
      });
    } catch (err) {
      console.error("Error saving data:", err);
      alert("❌ GAGAL! Periksa koneksi internet atau pengaturan Google Apps Script.");
