import { GoogleGenAI, Type } from "@google/genai";
import { KtpData } from "../types";

export const extractKtpData = async (base64Image: string): Promise<KtpData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const imageData = base64Image.split(',')[1] || base64Image;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageData,
          },
        },
        {
          text: `Extract all fields from this Indonesian KTP (ID Card).
          CRITICAL INSTRUCTIONS:
          1. Separate 'Tempat/Tgl Lahir' into 'tempatLahir' and 'tanggalLahir'.
          2. Separate 'RT/RW' into 'rt' and 'rw' (only the numbers).
          3. Respond strictly in JSON.
          4. If a field is not readable, return an empty string.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          nik: { type: Type.STRING },
          nama: { type: Type.STRING },
          tempatLahir: { type: Type.STRING, description: 'Place of birth only' },
          tanggalLahir: { type: Type.STRING, description: 'Date of birth only' },
          jenisKelamin: { type: Type.STRING },
          alamat: { type: Type.STRING },
          rt: { type: Type.STRING, description: 'RT number only' },
          rw: { type: Type.STRING, description: 'RW number only' },
          kelDesa: { type: Type.STRING },
          kecamatan: { type: Type.STRING },
          agama: { type: Type.STRING },
          statusPerkawinan: { type: Type.STRING },
          pekerjaan: { type: Type.STRING },
          kewarganegaraan: { type: Type.STRING },
          berlakuHingga: { type: Type.STRING },
        },
        required: ["nik", "nama"],
      },
    },
  });

  try {
    const jsonStr = response.text.trim();
    return JSON.parse(jsonStr) as KtpData;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("Gagal memproses data KTP. Pastikan foto cukup jelas.");
  }
};

