import React, { useState } from 'react';
import { CameraView } from './components/CameraView';
import { KtpForm } from './components/KtpForm';
import { extractKtpData } from './services/geminiService';
import { AppState } from './types';

/**
 * PENTING: Ganti URL di bawah ini dengan URL Web App dari Google Apps Script Anda.
 */
const GAS_URL = 'https://script.google.com/macros/s/AKfycbzyftPUx3cSSAGnKmiEwKNr9BQ64ACL3RH0oTB_07s0vIR-apUdZariVwmGkeGCGGZP/exec';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    image: null,
    extractedData: null,
    status: 'idle',
    errorMessage: null,
  });

  const [saving, setSaving] = useState(false);

  const handleCapture = async (base64: string) => {
    setState(prev => ({ ...prev, image: base64, status: 'processing', errorMessage: null }));

    try {
      const data = await extractKtpData(base64);
      setState(prev => ({ ...prev, extractedData: data, status: 'success' }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      setState(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMessage: err.message || "Gagal mengekstrak data. Pastikan gambar jelas." 
      }));
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        handleCapture(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveToSpreadsheet = async () => {
    if (!state.extractedData || !state.image) return;

    setSaving(true);
    try {
      await fetch(GAS_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...state.extractedData,
          image: state.image
        })
      });

      alert("✅ BERHASIL! Data & Foto KTP telah terkirim ke Google Sheets.");
      setState({
        image: null,
        extractedData: null,
        status: 'idle',
        errorMessage: null,
      });
    } catch (err) {
      console.error("Error saving data:", err);
      alert("❌ GAGAL! Periksa koneksi internet atau pengaturan Google Apps Script.");
    } finally {
      setSaving(false);
    }
  };

  const reset = () => {
    setState({
      image: null,
      extractedData: null,
      status: 'idle',
      errorMessage: null,
    });
