    } catch (err: any) {
      setState(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMessage: err.message || "Gagal mengekstrak data. Pastikan gambar jelas." 
      }));
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => handleCapture(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveToSpreadsheet = async () => {
    if (!state.extractedData || !state.image) return;

    setSaving(true);
    try {
      const payload = {
        ...state.extractedData,
        image: state.image,
        latitude: location?.lat,
        longitude: location?.lng
      };

      await fetch(GAS_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      setShowToast(true);
      setState(prev => ({ ...prev, status: 'saved' }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      console.error("Error saving data:", err);
      alert("❌ GAGAL! Periksa koneksi internet.");
    } finally {
      setSaving(false);
    }
  };

  const reset = () => {
    setState({
      image: null,
      extractedData: null,
      status: 'idle',
      errorMessage: null,
