        {state.status === 'processing' && (
          <div className="flex flex-col items-center justify-center p-12 bg-white rounded-[3rem] shadow-2xl w-full max-w-sm border border-gray-100 animate-pulse">
            <div className="relative">
              <div className="w-24 h-24 border-[6px] border-red-50 rounded-full" />
