            <p className="text-2xl font-black text-gray-800 mt-8 tracking-tighter">PROSES AI...</p>
            <p className="text-xs text-red-600 font-black uppercase tracking-widest mt-2">Mengekstrak Data KTP</p>
          </div>
        )}

        {state.status === 'saved' && (
          <div className="w-full max-w-md p-10 bg-white rounded-[3rem] shadow-2xl border-4 border-green-500 flex flex-col items-center text-center animate-in zoom-in duration-300">
            <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6">
