import React, { useState, useEffect, useCallback } from 'react';
import { CameraView } from './components/CameraView';
import { KtpForm } from './components/KtpForm';
import { KtpDetailModal } from './components/KtpDetailModal';
import { extractKtpData } from './services/geminiService';
import { AppState, KtpData, ViewMode } from './types';

const GAS_URL = 'https://script.google.com/macros/s/AKfycbyYJ2mEWd73pJnrniF7PkuI9B77mhDoe5QnN1yIqxNZH0865OY43jZqxeB_wELbAzLO/exec';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    image: null,
    extractedData: null,
    status: 'idle',
    errorMessage: null,
    viewMode: 'scanner',
    history: []
  });

  const [location, setLocation] = useState<{lat: number, lng: number} | null>(null);
  const [saving, setSaving] = useState(false);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [historyError, setHistoryError] = useState<string | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [selectedDetail, setSelectedDetail] = useState<KtpData | null>(null);

  useEffect(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        (err) => console.warn("Geolocation denied", err)
      );
    }
    fetchHistory();
  }, []);

  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(false), 4000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  const fetchHistory = useCallback(async () => {
    setLoadingHistory(true);
    setHistoryError(null);
    try {
      const cacheBuster = `t=${Date.now()}`;
      const urlWithCacheBuster = GAS_URL.includes('?') 
        ? `${GAS_URL}&${cacheBuster}` 
        : `${GAS_URL}?${cacheBuster}`;

      const response = await fetch(urlWithCacheBuster, {
        method: 'GET',
        headers: { 'Accept': 'application/json' }
      });

      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

      const result = await response.json();
      if (result.status === 'success') {
        setState(prev => ({ ...prev, history: result.data || [] }));
      } else {
        throw new Error(result.message || "Gagal mengambil data dari server.");
      }
    } catch (err: any) {
      console.error("Failed to fetch history:", err);
      setHistoryError("Gagal memuat riwayat.");
    } finally {
      setLoadingHistory(false);
    }
  }, []);

  const handleCapture = async (base64: string) => {
    setState(prev => ({ ...prev, image: base64, status: 'processing', errorMessage: null }));
    setIsCameraActive(false);
    try {
      const data = await extractKtpData(base64);
      const formattedData: KtpData = Object.keys(data).reduce((acc, key) => {
        const val = (data as any)[key];
        (acc as any)[key] = (typeof val === 'string' && key !== 'tanggalLahir') ? val.toUpperCase() : val;
        return acc;
      }, {} as KtpData);

      setState(prev => ({ ...prev, extractedData: formattedData, status: 'success' }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      setState(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMessage: err.message || "Gagal mengekstrak data. Pastikan gambar jelas." 
      }));
    }
  };

  const startManualInput = () => {
    const emptyData: KtpData = {
      nik: '',
      nama: '',
      tempatLahir: '',
      tanggalLahir: '',
      jenisKelamin: '',
      alamat: '',
      rt: '',
      rw: '',
      kelDesa: '',
      kecamatan: '',
      kotaKabupaten: '',
      agama: '',
      statusPerkawinan: '',
      pekerjaan: '',
      kewarganegaraan: 'WNI',
      berlakuHingga: 'SEUMUR HIDUP'
    };
    setState(prev => ({
      ...prev,
      image: null,
      extractedData: emptyData,
      status: 'success'
    }));
  };

  const handleSaveToSpreadsheet = async () => {
    if (!state.extractedData) return;

    const isDuplicate = state.history.some(item => item.nik === state.extractedData?.nik);
    if (isDuplicate) {
      alert(`⚠️ PERINGATAN: NIK ${state.extractedData.nik} sudah terdaftar dalam sistem riwayat lokal.`);
      return;
    }

    const requiredFields: (keyof KtpData)[] = [
      'nik', 'nama', 'tempatLahir', 'tanggalLahir', 'jenisKelamin', 
      'alamat', 'rt', 'rw', 'kelDesa', 'kecamatan', 'kotaKabupaten', 
      'agama', 'statusPerkawinan', 'pekerjaan', 'kewarganegaraan', 'berlakuHingga'
    ];

    const isInvalid = requiredFields.some(f => !state.extractedData![f]?.toString().trim());
    if (isInvalid || state.extractedData.nik.length !== 16) {
      alert("Mohon lengkapi semua data dengan benar.");
      return;
    }

    setSaving(true);
    try {
      const payload = {
        ...state.extractedData,
        image: state.image || "", 
        latitude: location?.lat,
        longitude: location?.lng
      };

      await fetch(GAS_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      setShowToast(true);
      setState(prev => ({ ...prev, status: 'saved' }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
      fetchHistory();
    } catch (err) {
      console.error("Error saving data:", err);
      alert("❌ GAGAL! Periksa koneksi internet.");
    } finally {
      setSaving(false);
    }
  };

  const reset = () => {
    setState(prev => ({
      ...prev,
      image: null,
      extractedData: null,
      status: 'idle',
      errorMessage: null,
    }));
    setShowToast(false);
    setIsCameraActive(false);
  };

  const changeView = (mode: ViewMode) => {
    setState(prev => ({ ...prev, viewMode: mode }));
    if (mode === 'history') fetchHistory();
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-6 md:py-12 pb-32 relative">
      <KtpDetailModal data={selectedDetail} onClose={() => setSelectedDetail(null)} />

      {/* TOAST */}
      {showToast && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-10 duration-500">
          <div className="bg-green-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 border-2 border-green-400">
            <div className="bg-white/20 p-1 rounded-full"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg></div>
            <span className="font-black uppercase tracking-widest text-xs">Data Tersimpan!</span>
          </div>
        </div>
      )}

      {/* NAVIGATION TABS */}
      {!isCameraActive && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-gray-900/90 backdrop-blur-xl p-2 rounded-[2rem] shadow-2xl flex gap-2 z-50 border border-white/10 animate-in fade-in slide-in-from-bottom-4 duration-300">
          <button 
            onClick={() => changeView('scanner')}
            className={`px-6 py-3 rounded-full flex items-center gap-2 transition-all ${state.viewMode === 'scanner' ? 'bg-red-600 text-white font-black' : 'text-gray-400 font-bold hover:text-white'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
            <span className="text-xs uppercase tracking-widest">Scanner</span>
          </button>
          <button 
            onClick={() => changeView('history')}
            className={`px-6 py-3 rounded-full flex items-center gap-2 transition-all ${state.viewMode === 'history' ? 'bg-red-600 text-white font-black' : 'text-gray-400 font-bold hover:text-white'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 10h16M4 14h16M4 18h16" /></svg>
            <span className="text-xs uppercase tracking-widest">Riwayat</span>
          </button>
        </div>
      )}

      <header className="text-center mb-8">
        <h1 className="text-3xl md:text-5xl font-black text-gray-900 leading-none tracking-tighter uppercase">
          KTP <span className="text-red-600">MBG</span> SCANNER
        </h1>
        <p className="text-[10px] text-gray-400 mt-2 font-black uppercase tracking-[0.4em]">Sistem Pendataan Lansia</p>
      </header>

      <main className="flex flex-col items-center gap-6">
        {state.viewMode === 'scanner' ? (
          <>
            {state.status === 'idle' && (
              <div className="w-full flex flex-col items-center gap-4 animate-in fade-in duration-500">
                <CameraView onCapture={handleCapture} onActiveChange={setIsCameraActive} />

                {!isCameraActive && (
                  <>
                    <label className="w-full max-w-xs cursor-pointer group flex items-center justify-center gap-3 px-6 py-4 bg-white border-2 border-gray-100 rounded-2xl hover:border-red-500 transition-all active:bg-red-50 shadow-sm">
                      <svg className="w-5 h-5 text-gray-400 group-hover:text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                      <span className="text-gray-700 group-hover:text-red-600 font-bold text-sm uppercase tracking-widest">PILIH DARI GALERI</span>
                      <input type="file" className="hidden" accept="image/*" onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                          const reader = new FileReader();
                          reader.onloadend = () => handleCapture(reader.result as string);
                          reader.readAsDataURL(file);
                        }
                      }} />
                    </label>

                    <button 
                      onClick={startManualInput}
                      className="w-full max-w-xs flex items-center justify-center gap-3 px-6 py-4 bg-gray-50 border-2 border-dashed border-gray-200 text-gray-500 rounded-2xl hover:border-gray-400 hover:text-gray-700 transition-all active:scale-95"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                      <span className="font-bold text-sm uppercase tracking-widest">INPUT MANUAL (KK)</span>
                    </button>
                  </>
                )}
              </div>
            )}

            {state.status === 'processing' && (
              <div className="flex flex-col items-center p-12 bg-white rounded-[3rem] shadow-2xl w-full max-w-sm border border-gray-50 animate-pulse">
                <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin" />
                <p className="text-lg font-black text-gray-800 mt-6 tracking-widest uppercase">Membaca KTP...</p>
              </div>
            )}

            {state.status === 'saved' && (
              <div className="w-full max-w-md p-10 bg-white rounded-[3rem] shadow-2xl border-4 border-green-500 flex flex-col items-center text-center animate-in zoom-in duration-300">
                <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6">
                  <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-900 mb-2">TERSIMPAN!</h2>
                <button onClick={reset} className="mt-4 px-8 py-4 bg-gray-900 text-white rounded-2xl font-black uppercase text-xs tracking-[0.2em]">Data Baru</button>
              </div>
            )}

            {state.status === 'success' && state.extractedData && (
              <div className="w-full animate-in fade-in slide-in-from-bottom-4 duration-700">
                <KtpForm 
                  data={state.extractedData}
                  onChange={(newData) => setState(prev => ({ ...prev, extractedData: newData }))}
                  onSubmit={handleSaveToSpreadsheet}
                  onReset={reset}
                  isLoading={saving}
                  history={state.history}
                />
              </div>
            )}

            {state.status === 'error' && (
              <div className="text-center p-10 bg-white rounded-[3rem] shadow-xl border-2 border-red-50">
                <p className="text-red-500 font-bold mb-6">{state.errorMessage}</p>
                <button onClick={reset} className="px-8 py-4 bg-red-600 text-white rounded-2xl font-black uppercase text-xs">Coba Lagi</button>
              </div>
            )}
          </>
        ) : (
          <div className="w-full animate-in fade-in duration-500 px-2 sm:px-0">
            {/* STATS HEADER */}
            <div className="bg-gray-900 rounded-[2.5rem] p-8 mb-8 shadow-2xl border border-white/10 relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/10 blur-[60px] rounded-full group-hover:bg-red-600/20 transition-all duration-700"></div>
              <div className="relative flex flex-col sm:flex-row justify-between items-center gap-6">
                <div className="text-center sm:text-left">
                   <h3 className="text-gray-400 font-black uppercase tracking-[0.3em] text-[10px] mb-2">Ringkasan Operasi</h3>
                   <h2 className="text-white text-3xl font-black tracking-tighter uppercase leading-none">Status <span className="text-red-600">Sinkronisasi</span></h2>
                </div>
                <div className="flex flex-col items-center bg-white/5 backdrop-blur-md px-8 py-4 rounded-3xl border border-white/10">
                   <span className="text-red-500 text-4xl font-black leading-none mb-1">{state.history.length}</span>
                   <span className="text-white text-[9px] font-black uppercase tracking-widest opacity-60">Total Terinput</span>
                </div>
              </div>
            </div>

            <div className="flex justify-between items-center mb-6 px-2">
              <h2 className="text-xl font-black text-gray-900 uppercase tracking-tight flex items-center gap-2">
                <div className="w-2 h-6 bg-red-600 rounded-full"></div>
                Data Terakhir
              </h2>
              <button onClick={fetchHistory} className="p-3 bg-white text-red-600 hover:bg-red-50 rounded-2xl shadow-sm border border-gray-100 transition-all active:scale-90" disabled={loadingHistory}>
                <svg className={`w-5 h-5 ${loadingHistory ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
              </button>
            </div>

            {state.history.length > 0 ? (
              <div className="flex flex-col gap-4">
                {state.history.map((item, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => setSelectedDetail(item)}
                    className="w-full text-left bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col md:flex-row md:items-center justify-between gap-4 group hover:shadow-xl hover:border-red-100 transition-all duration-300 active:scale-[0.98]"
                  >
                    <div className="flex gap-4 items-center">
                      <div className="w-14 h-14 bg-gray-50 group-hover:bg-red-50 rounded-2xl flex items-center justify-center text-gray-300 group-hover:text-red-400 font-black text-lg transition-colors">{state.history.length - idx}</div>
                      <div className="flex-1">
                        <h4 className="font-black text-gray-900 leading-tight mb-0.5 uppercase">{item.nama}</h4>
                        <p className="text-xs font-bold text-red-600 tracking-wider uppercase mb-1">{item.nik}</p>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-wide line-clamp-1">{item.alamat || '-'}</p>
                      </div>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                       <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-4 py-2 rounded-full uppercase tracking-widest border border-blue-100">DESA: {item.kelDesa || 'N/A'}</span>
                       {item.latitude && (
                         <span className="text-[9px] font-black bg-green-50 text-green-600 px-4 py-2 rounded-full uppercase tracking-widest border border-green-100">📍 Berlokasi</span>
                       )}
                       <div className="p-2 bg-gray-50 group-hover:bg-red-500 group-hover:text-white rounded-xl transition-all">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                          </svg>
                       </div>
                    </div>
                  </button>
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-white rounded-[2.5rem] border-2 border-dashed border-gray-100">
                {loadingHistory ? (
                   <div className="flex flex-col items-center gap-4">
                     <div className="w-10 h-10 border-4 border-gray-200 border-t-red-600 rounded-full animate-spin"></div>
                     <p className="text-gray-400 font-black uppercase text-xs tracking-widest">Sinkronisasi Server...</p>
                   </div>
                ) : (
                  <p className="text-gray-400 font-bold uppercase text-xs tracking-widest">Belum ada data masuk</p>
                )}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

/**
 * PANDUAN DEPLOY:
 * 1. ID SPREADSHEET: 1cbFUwktz2rV1L6X7x-iLXpTeIhIPhhaCCCr-R1HwawI
 * 2. ID FOLDER FOTO: 1NsfPsXjc5ErtlzfLHAf7qHXJ4Aq5iVWc
 * 3. Deploy sebagai 'Web App' -> 'Anyone' can access.
 */

const ID_SHEET = '1cbFUwktz2rV1L6X7x-iLXpTeIhIPhhaCCCr-R1HwawI';
const NAMA_SHEET = 'Sheet1';
const ID_FOLDER_FOTO = '1NsfPsXjc5ErtlzfLHAf7qHXJ4Aq5iVWc';

function doGet() {
  try {
    const ss = SpreadsheetApp.openById(ID_SHEET);
    const sheet = ss.getSheetByName(NAMA_SHEET) || ss.getSheets()[0];
    const rows = sheet.getDataRange().getValues();

    if (rows.length <= 1) {
      return ContentService.createTextOutput(JSON.stringify({ 
        status: 'success', 
        data: [] 
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // Ambil data dari baris ke-2 sampai akhir, urutkan dari yang terbaru (reverse)
    const dataRows = rows.slice(1).reverse().slice(0, 200);

    const data = dataRows.map(row => ({
      waktuInput: row[0],
      nik: row[1]?.toString().replace(/'/g, ""), 
      nama: row[2],
      tempatLahir: row[3],
      tanggalLahir: row[4] instanceof Date ? row[4].toISOString().split('T')[0] : row[4],
      jenisKelamin: row[5],
      alamat: row[6],
      rt: row[7]?.toString().replace(/'/g, ""),
      rw: row[8]?.toString().replace(/'/g, ""),
      kelDesa: row[9],
      kecamatan: row[10],
      kotaKabupaten: row[11],
      agama: row[12],
      statusPerkawinan: row[13],
      pekerjaan: row[14],
      kewarganegaraan: row[15],
      berlakuHingga: row[16],
      linkFoto: row[17],
      latitude: row[18],
      longitude: row[19]
    }));

    return ContentService.createTextOutput(JSON.stringify({ 
      status: 'success', 
      data: data 
    })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ 
      status: 'error', 
      message: err.toString() 
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(ID_SHEET);
    const sheet = ss.getSheetByName(NAMA_SHEET) || ss.getSheets()[0];

    const lastRow = sheet.getLastRow();
    if (lastRow > 1) {
      const nikColumnValues = sheet.getRange(2, 2, lastRow - 1, 1).getValues().flat();
      const incomingNik = data.nik?.toString().trim();
      const isDuplicate = nikColumnValues.some(val => val.toString().replace(/'/g, "").trim() === incomingNik);

      if (isDuplicate) {
        return ContentService.createTextOutput(JSON.stringify({ 
          status: 'error', 
          message: 'NIK sudah terdaftar sebelumnya' 
        })).setMimeType(ContentService.MimeType.JSON);
      }
    }

    if (sheet.getLastRow() === 0) {
      const headers = [
        'Waktu Input', 'NIK', 'Nama Lengkap', 'Tempat Lahir', 'Tanggal Lahir', 'Jenis Kelamin', 
        'Alamat', 'RT', 'RW', 'Kel/Desa', 'Kecamatan', 'Kota/Kabupaten', 'Agama', 
        'Status Perkawinan', 'Pekerjaan', 'Kewarganegaraan', 'Berlaku Hingga', 'Link Foto KTP',
        'Latitude', 'Longitude', 'Link Maps'
      ];
      sheet.appendRow(headers);
    }

    let fotoUrl = "Tidak Ada";
    if (data.image && ID_FOLDER_FOTO && data.image.length > 100) {
      try {
        const folder = DriveApp.getFolderById(ID_FOLDER_FOTO);
        const fileName = "KTP_" + (data.nik || "TMP") + "_" + new Date().getTime() + ".jpg";
        const base64Data = data.image.split(',')[1] || data.image;
        const blob = Utilities.newBlob(Utilities.base64Decode(base64Data), "image/jpeg", fileName);
        const file = folder.createFile(blob);
        file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        fotoUrl = file.getUrl();
      } catch (fError) {
        fotoUrl = "Gagal simpan foto";
      }
    }

    const mapsUrl = (data.latitude && data.longitude) 
      ? `https://www.google.com/maps?q=${data.latitude},${data.longitude}` 
      : "";

    sheet.appendRow([
      new Date(),
      "'" + (data.nik || ""),
      data.nama || "",
      data.tempatLahir || "",
      data.tanggalLahir || "",
      data.jenisKelamin || "",
      data.alamat || "",
      "'" + (data.rt || ""),
      "'" + (data.rw || ""),
      data.kelDesa || "",
      data.kecamatan || "",
      data.kotaKabupaten || "",
      data.agama || "",
      data.statusPerkawinan || "",
      data.pekerjaan || "",
      data.kewarganegaraan || "",
      data.berlakuHingga || "",
      fotoUrl,
      data.latitude || "",
      data.longitude || "",
      mapsUrl
    ]);

    return ContentService.createTextOutput(JSON.stringify({ status: 'success' })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}
